<template><ElSpace direction="vertical" fill class="v1-page" :size="20">
 <ElPageHeader title="天枢" content="告警中心" @back="$emit('navigate','overview')"><template #extra><ElSpace><ElButton @click="load">刷新</ElButton><ElButton :disabled="!admin" @click="newRule">新增规则</ElButton></ElSpace></template></ElPageHeader>
 <ElRow :gutter="20"><ElCol v-for="s in statuses" :key="s.value" :span="6"><ElCard shadow="never"><ElStatistic :title="s.label" :value="counts[s.value]||0" /></ElCard></ElCol></ElRow>
 <ElCard shadow="never"><ElSpace class="v1-gap"><ElSelect v-model="filter" @change="searchAlerts" clearable placeholder="处理状态" style="width:180px"><ElOption v-for="s in handling" :key="s.value" :value="s.value" :label="s.label" /></ElSelect><ElSelect v-model="severity" @change="searchAlerts" clearable placeholder="级别" style="width:160px"><ElOption value="warning" label="预警" /><ElOption value="critical" label="紧急" /></ElSelect><ElDatePicker v-model="dates" type="daterange" value-format="X" start-placeholder="开始日期" end-placeholder="结束日期" @change="searchAlerts" /></ElSpace><ArtTable :data="alerts" :show-table-header="false" height="440"><ElTableColumn prop="title" label="事件" min-width="180" /><ElTableColumn prop="device_name" label="设备" min-width="120" /><ElTableColumn label="监测状态"><template #default="{row}"><ElTag :type="row.machine_state==='active'?'danger':row.machine_state==='normal'?'success':'warning'">{{machine[row.machine_state]}}</ElTag></template></ElTableColumn><ElTableColumn label="处理状态"><template #default="{row}"><ElTag>{{handling.find(s=>s.value===row.handling_state)?.label}}</ElTag></template></ElTableColumn><ElTableColumn label="发生时间" min-width="175"><template #default="{row}">{{date(row.created)}}</template></ElTableColumn><ElTableColumn label="操作" width="100"><template #default="{row}"><ElButton text type="primary" @click="inspect(row)">处理</ElButton></template></ElTableColumn></ArtTable><ElPagination v-model:current-page="page" v-model:page-size="size" :total="total" :page-sizes="[20,50,100]" layout="total, sizes, prev, pager, next" class="v1-gap" @current-change="load" @size-change="searchAlerts" /></ElCard>
 <ElCard shadow="never"><template #header>预警规则</template><ArtTable :data="rules" :show-table-header="false" height="250"><ElTableColumn prop="name" label="规则" /><ElTableColumn label="指标"><template #default="{row}">{{metrics.find(x=>x.value===row.config.metric)?.label}}</template></ElTableColumn><ElTableColumn label="持续 / 秒"><template #default="{row}">{{row.config.duration}}</template></ElTableColumn><ElTableColumn label="状态"><template #default="{row}"><ElSwitch :model-value="!!row.enabled" :disabled="!admin" @change="v=>toggle(row,v)" /></template></ElTableColumn><ElTableColumn label="操作"><template #default="{row}"><ElButton text @click="editRule(row)">编辑</ElButton></template></ElTableColumn></ArtTable></ElCard>
 </ElSpace>
 <ElDrawer v-model="ruleOpen" title="预警规则" direction="rtl" size="min(560px,100vw)"><ArtForm :key="draft.id||'new'" v-model="draft" :items="ruleFields" :span="12" label-position="top" :show-reset="false" :show-submit="false" /><ElAlert v-if="error" :title="error" type="error" :closable="false" /><template #footer><ElButton @click="ruleOpen=false">取消</ElButton><ElButton type="primary" :loading="busy" @click="saveRule">保存</ElButton></template></ElDrawer>
 <ElDrawer v-model="incidentOpen" title="事件处理" direction="rtl" size="min(660px,100vw)"><template v-if="incident"><ElDescriptions :column="1" border><ElDescriptionsItem label="事件">{{incident.alert.title}}</ElDescriptionsItem><ElDescriptionsItem label="发生时间">{{date(incident.alert.created)}}</ElDescriptionsItem><ElDescriptionsItem label="监测状态">{{machine[incident.alert.machine_state]}}</ElDescriptionsItem><ElDescriptionsItem label="详情">{{incident.alert.message}}</ElDescriptionsItem></ElDescriptions><ArtForm v-model="treatment" :items="treatmentFields" :span="24" label-position="top" :show-reset="false" :show-submit="false" /><ElUpload :auto-upload="false" :limit="1" accept="image/png,image/jpeg,image/webp" :on-change="attach"><ElButton>现场照片</ElButton></ElUpload><ArtLineChart v-if="incident.samples.length" :data="incident.samples.map(s=>s.power_w)" :x-axis-data="incident.samples.map(s=>new Date(s.ts*1000).toLocaleTimeString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}))" height="200px" :smooth="false" /><ElEmpty v-else description="暂无事件曲线" /><ElTimeline class="v1-gap"><ElTimelineItem v-for="note in incident.notes" :key="note.id" :timestamp="date(note.ts)"><strong>{{note.actor}}</strong><p>{{note.note}}</p><ElImage v-if="note.photo" :src="note.photo" style="width:160px" :preview-src-list="[note.photo]" /></ElTimelineItem></ElTimeline><ElAlert v-if="error" :title="error" type="error" :closable="false" /></template><template #footer><ElButton @click="incidentOpen=false">关闭</ElButton><ElButton type="primary" :disabled="user.role==='viewer'" :loading="busy" @click="saveIncident">保存处理</ElButton></template></ElDrawer>
</template>
<script setup>
import {ref,computed,onMounted,onBeforeUnmount} from 'vue';import {ElMessage} from 'element-plus';import {api,date} from './api';
const props=defineProps({spaceId:String,user:Object,devices:Array});defineEmits(['navigate']);const counts=ref({}),total=ref(0),page=ref(1),size=ref(20),dates=ref(null),members=ref([]);const alerts=ref([]),rules=ref([]),filter=ref(''),severity=ref(''),draft=ref({}),ruleOpen=ref(false),incidentOpen=ref(false),incident=ref(null),treatment=ref({}),error=ref(''),busy=ref(false);const admin=computed(()=>['admin','demo'].includes(props.user.role));const machine={active:'异常',normal:'已恢复',unknown:'未知'};
const statuses=[{value:'active',label:'异常'},{value:'unknown',label:'未知'},{value:'in_progress',label:'处理中'},{value:'closed',label:'已关闭'}],handling=[{value:'pending',label:'待处理'},{value:'acknowledged',label:'已确认'},{value:'in_progress',label:'处理中'},{value:'closed',label:'已关闭'}];
const metrics=[{value:'power',label:'功率 / W'},{value:'daily_energy',label:'日用电 / kWh'},{value:'daily_cost',label:'日费用 / 元'},{value:'monthly_cost',label:'月费用 / 元'},{value:'balance',label:'剩余电量 / kWh'},{value:'remaining_hours',label:'可用时间 / 小时'},{value:'off_hours',label:'非营业时段功率 / W'},{value:'offline',label:'离线'},{value:'stalled',label:'读数停滞 / 秒'}];const f=(key,label,type='input',props={})=>({key,label,type,props});
const ruleFields=computed(()=>[f('name','名称'),f('config.metric','指标','select',{options:metrics}),f('config.device_id','设备','select',{clearable:true,options:props.devices.map(d=>({value:d.id,label:d.name}))}),f('config.threshold','阈值','number',{min:0}),f('config.level','级别','select',{options:[{value:'warning',label:'预警'},{value:'critical',label:'紧急'}]}),f('config.duration','持续 / 秒','number',{min:0}),f('config.recovery','恢复稳定 / 秒','number',{min:0}),f('config.hysteresis','恢复滞回','number',{min:0}),f('config.cooldown','通知间隔 / 秒','number',{min:60}),f('config.escalate_after','超时升级 / 秒','number',{min:0}),f('config.start','营业开始','timepicker',{format:'HH:mm',valueFormat:'HH:mm'}),f('config.end','营业结束','timepicker',{format:'HH:mm',valueFormat:'HH:mm'})]);const treatmentFields=computed(()=>[f('assigned_to','负责人','select',{clearable:true,options:members.value.map(m=>({label:m.username,value:m.id}))}),f('handling_state','处理状态','select',{options:handling}),f('note','处理说明','input',{type:'textarea',rows:4})]);
async function load(){try{const q=new URLSearchParams({space_id:props.spaceId,page:page.value,size:size.value});if(filter.value)q.set('handling',filter.value);if(severity.value)q.set('level',severity.value);if(dates.value){q.set('from',dates.value[0]);q.set('to',Number(dates.value[1])+86399)}const [a,r,m]=await Promise.all([api('alerts?'+q),api('rules?space_id='+props.spaceId),api('space-assignees?space_id='+props.spaceId)]);alerts.value=a.alerts;total.value=a.total;counts.value=a.counts;rules.value=r.rules;members.value=m.members}catch(e){ElMessage.error(e.message)}}
function searchAlerts(){page.value=1;load()}
function newRule(){draft.value={name:'',enabled:true,config:{metric:'power',threshold:1500,duration:120,recovery:30,hysteresis:100,cooldown:3600,escalate_after:1800,start:'08:00',end:'18:00'}};error.value='';ruleOpen.value=true}function editRule(r){draft.value=JSON.parse(JSON.stringify(r));error.value='';ruleOpen.value=true}
async function saveRule(){busy.value=true;try{await api('rules',{...draft.value,space_id:props.spaceId});ruleOpen.value=false;await load()}catch(e){error.value=e.message}finally{busy.value=false}}
async function toggle(r,v){try{await api('rules',{...r,enabled:v});await load()}catch(e){ElMessage.error(e.message)}}
async function inspect(a){try{incident.value=await api('incident?id='+a.id);treatment.value={id:a.id,handling_state:incident.value.alert.handling_state,assigned_to:incident.value.alert.assigned_to,note:'',photo:''};error.value='';incidentOpen.value=true}catch(e){ElMessage.error(e.message)}}
async function saveIncident(){busy.value=true;try{await api('incident',treatment.value);await inspect({id:treatment.value.id,handling_state:treatment.value.handling_state});await load();ElMessage.success('已保存')}catch(e){error.value=e.message}finally{busy.value=false}}
function attach(file){if(file.size>128*1024){ElMessage.error('照片应小于128KB');return}const reader=new FileReader();reader.onload=()=>treatment.value.photo=reader.result;reader.readAsDataURL(file.raw)}let timer;onMounted(()=>{load();timer=setInterval(load,15000)});onBeforeUnmount(()=>clearInterval(timer));
</script>
